CREATE TABLE public.trainer_permissions (user_id uuid PRIMARY KEY, reports boolean NOT NULL DEFAULT false, assignments boolean NOT NULL DEFAULT false, granted_by uuid NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.trainer_permissions TO authenticated; GRANT ALL ON public.trainer_permissions TO service_role;
ALTER TABLE public.trainer_permissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read trainer permissions" ON public.trainer_permissions FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.training_access(_permission text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') OR (public.has_role(auth.uid(),'trainer') AND EXISTS(SELECT 1 FROM public.trainer_permissions WHERE user_id=auth.uid() AND CASE _permission WHEN 'reports' THEN reports WHEN 'assignments' THEN assignments ELSE false END)) $$;
REVOKE ALL ON FUNCTION public.training_access(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.training_access(text) TO authenticated;
CREATE OR REPLACE FUNCTION public.is_staff(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(_user_id,'admin') $$;
CREATE TABLE public.training_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid NOT NULL, target_id uuid, action text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.training_audit TO authenticated; GRANT ALL ON public.training_audit TO service_role;
ALTER TABLE public.training_audit ENABLE ROW LEVEL SECURITY; CREATE POLICY "owner audit" ON public.training_audit FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.set_trainer_access(_target uuid,_reports boolean,_assignments boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=_target) THEN RAISE EXCEPTION 'Account not found'; END IF; IF public.has_role(_target,'admin') THEN RAISE EXCEPTION 'Owner permissions cannot be changed here'; END IF; INSERT INTO public.trainer_permissions(user_id,reports,assignments,granted_by) VALUES(_target,_reports,_assignments,auth.uid()) ON CONFLICT(user_id) DO UPDATE SET reports=excluded.reports, assignments=excluded.assignments,granted_by=excluded.granted_by,updated_at=now(); IF _reports OR _assignments THEN INSERT INTO public.user_roles(user_id,role) VALUES(_target,'trainer') ON CONFLICT DO NOTHING; ELSE DELETE FROM public.user_roles WHERE user_id=_target AND role='trainer'; END IF; INSERT INTO public.training_audit(actor_id,target_id,action,details) VALUES(auth.uid(),_target,'trainer_access',jsonb_build_object('reports',_reports,'assignments',_assignments)); END $$;
REVOKE ALL ON FUNCTION public.set_trainer_access(uuid,boolean,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.set_trainer_access(uuid,boolean,boolean) TO authenticated;
CREATE TABLE public.training_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), student_id uuid NOT NULL, trainer_id uuid NOT NULL, title text NOT NULL CHECK(length(title) BETWEEN 1 AND 200), notes text NOT NULL DEFAULT '', due_date date NOT NULL, completed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.training_assignments TO authenticated; GRANT ALL ON public.training_assignments TO service_role;
ALTER TABLE public.training_assignments ENABLE ROW LEVEL SECURITY;
CREATE POLICY "assignment reads" ON public.training_assignments FOR SELECT TO authenticated USING(student_id=auth.uid() OR public.training_access('assignments'));
CREATE POLICY "assignment create" ON public.training_assignments FOR INSERT TO authenticated WITH CHECK(public.training_access('assignments') AND trainer_id=auth.uid());
CREATE POLICY "assignment manage" ON public.training_assignments FOR DELETE TO authenticated USING(public.training_access('assignments') AND (trainer_id=auth.uid() OR public.has_role(auth.uid(),'admin')));
CREATE FUNCTION public.complete_training_assignment(_id uuid,_completed boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.training_assignments SET completed=_completed WHERE id=_id AND student_id=auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'Assignment not found'; END IF; END $$;
REVOKE ALL ON FUNCTION public.complete_training_assignment(uuid,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.complete_training_assignment(uuid,boolean) TO authenticated;
CREATE TABLE public.certificate_courses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL CHECK(length(title) BETWEEN 1 AND 200), skills text[] NOT NULL, required_lessons text[] NOT NULL CHECK(cardinality(required_lessons)>0), final_test_id uuid NOT NULL REFERENCES public.tests(id), pass_percent integer NOT NULL DEFAULT 70 CHECK(pass_percent BETWEEN 1 AND 100), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.certificate_courses TO authenticated; GRANT ALL ON public.certificate_courses TO service_role;
ALTER TABLE public.certificate_courses ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read certificate courses" ON public.certificate_courses FOR SELECT TO authenticated USING(active OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "owner courses" ON public.certificate_courses FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.verified_lesson_results (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, lesson_slug text NOT NULL, score integer NOT NULL CHECK(score>=0), total integer NOT NULL CHECK(total>0), completed boolean NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,lesson_slug), CHECK(score<=total));
GRANT SELECT ON public.verified_lesson_results TO authenticated; GRANT ALL ON public.verified_lesson_results TO service_role;
ALTER TABLE public.verified_lesson_results ENABLE ROW LEVEL SECURITY;
CREATE POLICY "verified lesson reads" ON public.verified_lesson_results FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.issued_certificates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, course_id uuid NOT NULL REFERENCES public.certificate_courses(id), student_name text NOT NULL, course_title text NOT NULL, skills text[] NOT NULL, assessment_percent numeric NOT NULL, issued_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, revocation_reason text, UNIQUE(user_id,course_id));
GRANT SELECT ON public.issued_certificates TO authenticated; GRANT ALL ON public.issued_certificates TO service_role;
ALTER TABLE public.issued_certificates ENABLE ROW LEVEL SECURITY;
CREATE POLICY "certificate reads" ON public.issued_certificates FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.issue_course_certificate(_course uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.certificate_courses; n text; pct numeric; cid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; SELECT * INTO c FROM public.certificate_courses WHERE id=_course AND active; IF NOT FOUND THEN RAISE EXCEPTION 'Course unavailable'; END IF; IF EXISTS(SELECT 1 FROM unnest(c.required_lessons) s WHERE NOT EXISTS(SELECT 1 FROM public.verified_lesson_results r WHERE r.user_id=auth.uid() AND r.lesson_slug=s AND r.completed)) THEN RAISE EXCEPTION 'Complete all required lesson quizzes first'; END IF; SELECT max(accuracy) INTO pct FROM public.test_attempts WHERE user_id=auth.uid() AND test_id=c.final_test_id AND submitted_at IS NOT NULL AND total>0; IF pct IS NULL OR pct<c.pass_percent THEN RAISE EXCEPTION 'Final assessment score is below the requirement'; END IF; SELECT full_name INTO n FROM public.profiles WHERE id=auth.uid(); IF n IS NULL OR length(trim(n))=0 THEN RAISE EXCEPTION 'Add your full name to your profile first'; END IF; INSERT INTO public.issued_certificates(user_id,course_id,student_name,course_title,skills,assessment_percent) VALUES(auth.uid(),c.id,n,c.title,c.skills,pct) ON CONFLICT(user_id,course_id) DO NOTHING RETURNING id INTO cid; IF cid IS NULL THEN SELECT id INTO cid FROM public.issued_certificates WHERE user_id=auth.uid() AND course_id=c.id AND revoked_at IS NULL; END IF; IF cid IS NULL THEN RAISE EXCEPTION 'Certificate revoked; contact your trainer'; END IF; RETURN cid; END $$;
REVOKE ALL ON FUNCTION public.issue_course_certificate(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.issue_course_certificate(uuid) TO authenticated;
CREATE FUNCTION public.manage_course_certificate(_id uuid,_name text,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; IF _reason IS NOT NULL THEN UPDATE public.issued_certificates SET revoked_at=now(),revocation_reason=left(_reason,500) WHERE id=_id; ELSIF _name IS NOT NULL AND length(trim(_name)) BETWEEN 1 AND 150 THEN UPDATE public.issued_certificates SET student_name=trim(_name) WHERE id=_id; ELSE RAISE EXCEPTION 'Provide a correction or revocation reason'; END IF; IF NOT FOUND THEN RAISE EXCEPTION 'Certificate not found'; END IF; INSERT INTO public.training_audit(actor_id,action,details) VALUES(auth.uid(),CASE WHEN _reason IS NULL THEN 'certificate_corrected' ELSE 'certificate_revoked' END,jsonb_build_object('certificate_id',_id)); END $$;
REVOKE ALL ON FUNCTION public.manage_course_certificate(uuid,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.manage_course_certificate(uuid,text,text) TO authenticated;
CREATE FUNCTION public.verify_course_certificate(_id uuid) RETURNS TABLE(id uuid,student_name text,course_title text,skills text[],issued_at timestamptz,revoked boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT id,student_name,course_title,skills,issued_at,revoked_at IS NOT NULL FROM public.issued_certificates WHERE id=_id $$;
REVOKE ALL ON FUNCTION public.verify_course_certificate(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.verify_course_certificate(uuid) TO anon,authenticated;
DROP POLICY IF EXISTS "own lesson progress select" ON public.lesson_progress;
CREATE POLICY "own lesson progress select" ON public.lesson_progress FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
